template:
use std::error::Error;
use std::fmt;

#[derive(Debug)]
struct BadHeader;

impl fmt::Display for BadHeader {
    fn fmt(
        &self,
        f: &mut fmt::Formatter,
    ) -> fmt::Result {
        write!(f, "bad header")
    }
}

impl ⟦slot1⟧ for ⟦slot2⟧ {}

fn check() -> Result<(), Box<dyn Error>> {
    Err(BadHeader)?;
    Ok(())
}

fn main() {
    let _ = check();
}

tests:
#[test]
fn test_check() {
    let res = check();
    assert!(res.is_err());
    assert_eq!(res.unwrap_err().to_string(), "bad header");
}
